1	import { db } from "./db";
2	import { ovh, ovhApi, ovhConfigured } from "./ovh";
3	import { SANDBOX, sandboxIp, sandboxMac } from "./sandbox";
4	import { getSettingInt } from "./settings";
5	
6	const SERVER = process.env.OVH_SERVER_NAME ?? "ns5002569.ip-51-79-162.net";
7	/**
8	 * Fallback monthly price for a dedicated IPv4. Defaults to 0 — a dedicated IP is
9	 * INCLUDED on every plan (its cost is folded into plan pricing, as the marketing
10	 * pages state). The admin `dedicated_ip_price_cents` setting is the source of
11	 * truth; use `dedicatedIpMonthlyCents()` in billing paths, not this constant.
12	 */
13	export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 0);
14	
15	/**
16	 * The monthly dedicated-IP surcharge actually charged, from the admin setting
17	 * (`dedicated_ip_price_cents`, default 0 = included). Single source of truth for
18	 * every order/renewal/display path so they can never disagree.
19	 */
20	export async function dedicatedIpMonthlyCents(): Promise<number> {
21	  return getSettingInt("dedicated_ip_price_cents", DEDICATED_IP_PRICE_CENTS);
22	}
23	/** Keep this many spare IPs in the pool; auto-order/release aims to stay near it. */
24	export const DEDICATED_IP_BUFFER = Number(process.env.DEDICATED_IP_BUFFER ?? 2);
25	
26	/** OVH failover gateway = the host's /24 gateway (…​.254). */
27	export function ovhGateway(): string {
28	  const ip = process.env.PUBLIC_IP ?? "51.79.162.96";
29	  const parts = ip.split(".");
30	  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
31	}
32	
33	/**
34	 * Pull additional/failover IPv4 addresses routed to our server from OVH and
35	 * upsert them into the pool. The host's own primary IP is never poolable.
36	 */
37	export async function syncDedicatedIpPool(): Promise<{ imported: number; total: number }> {
38	  if (SANDBOX) return { imported: 0, total: 0 };
39	  if (!ovhConfigured()) return { imported: 0, total: 0 };
40	  const primary = process.env.PUBLIC_IP;
41	  const blocks: string[] = await ovhApi.ips();
42	  let imported = 0;
43	  for (const block of blocks) {
44	    if (block.includes(":")) continue; // IPv6 handled separately
45	    let info: any;
46	    try {
47	      info = await ovhApi.ipInfo(block);
48	    } catch {
49	      continue;
50	    }
51	    if (info?.routedTo?.serviceName !== SERVER) continue;
52	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
53	    // A /32 block is a single usable IP == the block minus the mask.
54	    const address = block.split("/")[0];
55	    if (address === primary) continue;
56	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
57	    if (!existing) {
58	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, status: "FREE" } });
59	      imported++;
60	    }
61	  }
62	  const total = await db.dedicatedIp.count();
63	  return { imported, total };
64	}
65	
66	export async function freeCount(): Promise<number> {
67	  return db.dedicatedIp.count({ where: { status: "FREE" } });
68	}
69	
70	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
71	async function findVirtualMacForIp(address: string): Promise<string | null> {
72	  const macs: string[] = await ovh("GET", `/dedicated/server/${SERVER}/virtualMac`).catch(() => []);
73	  for (const m of macs) {
74	    const ips: string[] = await ovh(
75	      "GET",
76	      `/dedicated/server/${SERVER}/virtualMac/${m}/virtualAddress`
77	    ).catch(() => []);
78	    if (ips.includes(address)) return m;
79	  }
80	  return null;
81	}
82	
83	/**
84	 * Claim a free IP for a server and create its OVH Virtual MAC so the VM can use it.
85	 * Returns the address + virtualMac + gateway, or null if none available.
86	 */
87	export async function allocateDedicatedIp(
88	  serverId: string,
89	  vmid: number
90	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
91	  if (SANDBOX) {
92	    // Hand out a synthetic dedicated IP without any OVH call or pool mutation.
93	    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
94	  }
95	  if (!ovhConfigured()) return null;
96	  // Atomically claim a FREE ip
97	  const claim = await db.$transaction(async (tx) => {
98	    const ip = await tx.dedicatedIp.findFirst({ where: { status: "FREE" }, orderBy: { createdAt: "asc" } });
99	    if (!ip) return null;
100	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
101	    return ip;
102	  });
103	  if (!claim) return null;
104	
105	  try {
106	    // Reuse an existing vMAC for this IP if one is already bound; else create one.
107	    let mac = await findVirtualMacForIp(claim.address);
108	    if (!mac) {
109	      // Creation is asynchronous (returns a task) — kick it off then poll.
110	      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
111	      for (let i = 0; i < 40 && !mac; i++) {
112	        await new Promise((r) => setTimeout(r, 3000));
113	        mac = await findVirtualMacForIp(claim.address);
114	      }
115	    }
116	    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
117	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
118	    return { address: claim.address, virtualMac: mac, gateway: ovhGateway() };
119	  } catch (e) {
120	    // Roll the claim back to FREE on failure
121	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
122	    throw e;
123	  }
124	}
125	
126	/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual MAC). */
127	export async function releaseDedicatedIp(serverId: string): Promise<void> {
128	  if (SANDBOX) return;
129	  const ip = await db.dedicatedIp.findUnique({ where: { serverId } });
130	  if (!ip) return;
131	  if (ovhConfigured() && ip.virtualMac) {
132	    try {
133	      // Remove the IP from the vMAC, then delete the vMAC.
134	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
135	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
136	    } catch {
137	      /* best-effort */
138	    }
139	  }
140	  await db.dedicatedIp.update({
141	    where: { id: ip.id },
142	    data: { status: "FREE", serverId: null, virtualMac: null },
143	  });
144	}
145	
146	/** Set reverse DNS (PTR) for a dedicated IP. */
147	export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
148	  if (!ovhConfigured()) return;
149	  await ovhApi.setReverse(`${address}/32`, address, reverse);
150	  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
151	}
