34	async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any }> {
35	  const server = await db.server.findUnique({
36	    where: { id: job.serverId! },
37	    include: { plan: true, osTemplate: true, node: true },
38	  });
39	  if (!server) throw new Error(`Server ${job.serverId} not found`);
40	  return server as any;
41	}
42	
43	/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
44	async function nodeFor(server: any) {
45	  const n =
46	    server.node ??
47	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
48	    (await db.node.findFirst({ where: { enabled: true } }));
49	  if (!n) {
50	    // No Node rows yet — use the env-configured primary via the global client.
51	    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
52	  }
53	  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
54	}
