56	/** YAML-safe indent of a multi-line script under a `content: |` block. */
57	function indentBlock(text: string, spaces: number): string {
58	  const pad = " ".repeat(spaces);
59	  return text.split("\n").map((l) => pad + l).join("\n");
60	}
61	
62	/**
63	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
64	 * plus any control-panel/app install script and selected add-ons. Long installs
65	 * run in the background so the VM reports ready promptly.
66	 */
67	function buildCloudInit(server: any): string {
68	  const addons = (server.addons ?? {}) as {
69	    malwareScanner?: boolean;
70	    dailyBackup?: boolean;
71	    docker?: boolean;
72	    claudeCode?: boolean;
73	  };
74	  const setup: string[] = [];
75	
76	  // Pre-bake Claude Code (Anthropic CLI) on every server unless explicitly opted
77	  // out. Customers SSH in and run `claude` using their own subscription or API
78	  // key — no setup on our side, zero token cost to us. Installs run in the
79	  // background (nohup below) so the VM still reports ready quickly.
80	  if (addons.claudeCode !== false) {
81	    setup.push(
82	      "# --- Nxeon: pre-install Claude Code (Anthropic CLI) ---",
83	      "(apt-get install -y git curl ca-certificates || dnf install -y git curl ca-certificates || true)",
84	      "if ! command -v node >/dev/null 2>&1; then " +
85	        "(curl -fsSL https://deb.nodesource.com/setup_20.x | bash - && apt-get install -y nodejs) || " +
86	        "(curl -fsSL https://rpm.nodesource.com/setup_20.x | bash - && dnf install -y nodejs) || " +
87	        "(apt-get install -y nodejs npm || true); fi",
88	      "npm install -g @anthropic-ai/claude-code || true",
89	      "command -v claude >/dev/null 2>&1 && echo 'Claude Code installed' >> /var/log/nxeon-setup.log || true",
90	    );
91	  }
92	
93	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
94	  if (addons.malwareScanner)
95	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
96	  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);
97	
98	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
99	
100	  // A friendly first-login guide + MOTD banner pointing at the portal hub.
101	  const welcome = [
102	    "# Welcome to your Nxeon server",
103	    "",
104	    "## Build anything with Claude Code — it's already installed",
105	    "",
106	    "1. You're already logged in. Just run:",
107	    "",
108	    "   claude",
109	    "",
110	    "2. Sign in once — either with your Claude subscription (Pro/Max) or an",
111	    "   Anthropic API key. See the step-by-step guide with screenshots at:",
112	    "",
113	    "   https://nxeon.cloud/dashboard/claude-code",
114	    "",
115	    "3. Then describe what you want in plain English, for example:",
116	    '   "Build a modern website for my coffee shop with a menu and contact form,',
117	    '    then run it and tell me the URL to preview it."',
118	    "",
119	    "Copy-paste starter prompts (spa site, booking app, REST API, Discord bot,",
120	    "and 20+ more) and how-to guides live in your portal at the link above.",
121	    "",
122	    "Happy building!",
123	  ].join("\n");
124	
125	  const motd = [
126	    "#!/bin/sh",
127	    'if [ -t 1 ]; then',
128	    '  printf "\\n  \\033[1mNxeon\\033[0m — Claude Code is pre-installed on this server.\\n"',
129	    '  printf "  Run \\033[1mclaude\\033[0m to start building. Guide: https://nxeon.cloud/dashboard/claude-code\\n"',
130	    '  printf "  Full walkthrough: \\033[2m~/START-WITH-CLAUDE.md\\033[0m\\n\\n"',
131	    "fi",
132	  ].join("\n");
133	
134	  return `#cloud-config
135	package_update: true
136	packages:
137	  - qemu-guest-agent
138	ssh_pwauth: true
139	disable_root: false
140	write_files:
141	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
142	    permissions: "0644"
143	    content: |
144	      PermitRootLogin yes
145	      PasswordAuthentication yes
146	  - path: /root/START-WITH-CLAUDE.md
147	    permissions: "0644"
148	    content: |
149	${indentBlock(welcome, 6)}
150	  - path: /etc/profile.d/nxeon-welcome.sh
151	    permissions: "0755"
152	    content: |
153	${indentBlock(motd, 6)}
154	  - path: /root/nxeon-setup.sh
155	    permissions: "0755"
156	    content: |
157	${indentBlock(script, 6)}
158	runcmd:
159	  - systemctl enable --now qemu-guest-agent
160	  - systemctl restart ssh || systemctl restart sshd
161	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
162	`;
163	}
164	
165	const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
166	const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";
167	
168	async function provision(job: Job) {
169	  const server = await loadServer(job);
170	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });
171	
172	  if (SANDBOX) {
173	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
174	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
175	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
176	    const password = generatePassword();
177	    const ip = sandboxIp(vmid);
178	    await db.server.update({
179	      where: { id: server.id },
180	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: password, status: "RUNNING" },
181	    });
182	    await notify(
183	      server.userId,
184	      `Server ${server.hostname} is ready`,
185	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
186	      `/dashboard/servers/${server.id}`
187	    );
188	    return;
189	  }
190	
191	  const { conn, row: nodeRow } = await nodeFor(server);
192	  const storage = server.plan.storageTier === "hdd"
193	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
194	    : nodeRow?.storageNvme ?? "vmdata";
195	
196	  const vmid = server.vmid ?? (await conn.nextVmid());
197	  const password = generatePassword();
198	
199	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
200	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
201	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
202	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
203	  const { getSettingBool: _settingBool } = await import("../lib/settings");
204	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
205	  if (wantDedicated && ovhConfigured()) {
206	    try {
207	      dedicated = await allocateDedicatedIp(server.id, vmid);
208	    } catch (e) {
209	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
210	    }
211	  }
212	  // Node-aware + transactionally-claimed allocation (passing the server id enables
213	  // the claim path, so two concurrent provisions can't pick the same IP/port).
214	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
215	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
216	
217	  await db.server.update({
218	    where: { id: server.id },
219	    data: { vmid, ipAddress: ip, sshPort, rootPassword: password },
220	  });
221	
222	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
223	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
224	  // (worker restart mid-clone, or any transient failure in the steps below) would
225	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
226	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
227	  // the clone is idempotent, so skip it when the VM is already present.
228	  let vmAlreadyExists = false;
229	  try {
230	    await conn.vmStatus(vmid);
231	    vmAlreadyExists = true;
232	  } catch {
233	    vmAlreadyExists = false;
234	  }
235	  if (vmAlreadyExists) {
236	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
237	  } else {
238	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
239	      newid: vmid,
240	      name: server.hostname,
241	      full: 1,
242	      storage,
243	    });
244	    await conn.waitForTask(cloneUpid, 600_000);
245	  }
246	
247	  // Per-server cloud-init snippet (base + panel/app install + add-ons)
248	  const snippet = buildCloudInit(server);
249	  await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8").catch((e) =>
250	    console.error("[worker] snippet write failed", e)
251	  );
252	
253	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
254	  const sshkeys = keys.length
255	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
256	    : undefined;
257	  const cfg: Record<string, any> = {
258	    cores: server.plan.cpuCores,
259	    memory: server.plan.ramMB,
260	    ciuser: "root",
261	    cipassword: password,
262	    sshkeys,
263	    nameserver: "1.1.1.1 8.8.8.8",
264	    onboot: 1,
265	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
266	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
267	  };
268	  if (dedicated) {
269	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
270	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
271	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
272	  } else {
273	    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
274	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
275	  }
276	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
277	
278	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
279	    disk: "scsi0",
280	    size: `${server.plan.diskGB}G`,
281	  });
282	
283	  if (!SANDBOX && !dedicated) await syncPortForwards();
284	
285	  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
286	  await conn.waitForTask(startUpid);
287	
288	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
289	  const isImage = server.osTemplate.category !== "PLAIN_OS";
290	  const sshLine = dedicated
291	    ? `ssh root@${dedicated.address}`
