334	async function remove(job: Job) {
335	  const server = await loadServer(job);
336	  const { conn } = await nodeFor(server);
337	  if (!SANDBOX && server.vmid) {
338	    try {
339	      await destroyVm(conn, server.vmid);
340	    } catch (e: any) {
341	      // VM may never have been created; only swallow "does not exist"
342	      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
343	    }
344	    // Best-effort: remove the per-server cloud-init snippet
345	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
346	  }
347	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
348	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
349	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
350	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
351	  // diskName and keep billing forever. Remove them and notify the owner. (The
352	  // reinstall guard already blocks the accidental case; a full server delete is an
353	  // intentional teardown, so we drop the volumes with it.)
354	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
355	  if (orphanVolumes.length > 0) {
356	    await db.volume.deleteMany({ where: { serverId: server.id } });
357	    for (const v of orphanVolumes) {
358	      await notify(
359	        v.userId,
360	        `Volume "${v.name}" was removed`,
361	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
362	        "/dashboard/volumes",
363	      ).catch(() => {});
364	    }
365	  }
366	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
367	  // server.delete cascade removes THIS running Job row — the success-path
368	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
369	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
370	  await db.server.delete({ where: { id: server.id } });
371	  if (!SANDBOX) await syncPortForwards();
372	}
