392	async function suspend(job: Job, unsuspend: boolean) {
393	  const server = await loadServer(job);
394	  if (SANDBOX) {
395	    if (unsuspend) {
396	      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null } });
397	    } else {
398	      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
399	    }
400	    return;
401	  }
402	  const { conn, row: nodeRow } = await nodeFor(server);
403	  if (unsuspend) {
404	    // The dedicated IP was returned to the pool while suspended — re-allocate one
405	    // and reconfigure the public network before starting the VM back up.
406	    if (server.vmid) {
407	      const { getSettingBool: _sb } = await import("../lib/settings");
408	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
409	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
410	      let reconfigured = alreadyHas ? true : false;
411	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
412	        try {
413	          const d = await allocateDedicatedIp(server.id, server.vmid);
414	          if (d) {
415	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
416	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
417	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
418	            });
419	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
420	            reconfigured = true;
421	          }
422	        } catch (e) {
423	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
424	        }
425	      }
426	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
427	      // the Virtual MAC + failover IP that suspend released back to the pool — that
428	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
429	      // with a valid, non-conflicting network instead of a dead public config.
430	      if (!reconfigured) {
431	        try {
432	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
433	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
434	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
435	            net0: `virtio,bridge=${nodeRow?.bridge ?? "vmbr1"}`,
436	            ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`,
437	          });
438	          await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort } });
439	        } catch (e) {
440	          console.error("[worker] NAT fallback on unsuspend failed", e);
441	        }
442	      }
443	    }
444	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null } });
445	    if (!SANDBOX) await syncPortForwards();
446	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
447	    await conn.waitForTask(upid);
448	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
449	  } else {
450	    try {
451	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
452	      await conn.waitForTask(upid);
453	    } catch { /* may already be stopped */ }
454	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
455	    if (!SANDBOX) await syncPortForwards();
456	    // Return the dedicated IP to the pool while the server is suspended, so it
457	    // can be handed to a paying server. Re-allocated on unsuspend.
458	    if (ovhConfigured()) {
459	      try {
460	        const had = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
461	        if (had) {
462	          await releaseDedicatedIp(server.id);
463	          // MUST also clear the address off the server: `Server.ipAddress` is UNIQUE,
464	          // so leaving the released IP here makes the next server that claims it fail
465	          // with P2002 — that server then silently lands on NAT while its OVH Virtual
466	          // MAC stays allocated and billable. (NAT servers keep their private IP.)
467	          await db.server.update({
468	            where: { id: server.id },
469	            data: { ipAddress: null, ipv6: null },
470	          });
471	        }
472	      } catch (e) {
473	        console.error("[worker] release dedicated IP on suspend failed", e);
474	      }
475	    }
476	  }
477	}
