668	/**
669	 * Reverse a money side-effect that a job committed up-front but never delivered.
670	 * Server actions charge/credit the wallet before enqueuing the worker job (so the
671	 * UI reflects the change immediately); if the job then fails terminally the money
672	 * must be unwound or the customer is charged for a resize that never happened
673	 * (up) or keeps a downgrade credit for hardware they still have (down).
674	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
675	 * double-reverse.
676	 */
677	async function reconcileFailedJob(job: Job) {
678	  if (job.type !== "RESIZE") return;
679	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
680	  const cents = p.prorateCents ?? 0;
681	  if (cents <= 0 || !job.serverId) return;
682	
683	  // Idempotency: skip if we already reversed this exact job.
684	  const already = await db.auditLog.findFirst({
685	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
686	  });
687	  if (already) return;
688	
689	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
690	  if (!server) return;
691	
692	  try {
693	    if (p.direction === "up") {
694	      // Upgrade charge never delivered → refund the prorated charge.
695	      await db.$transaction([
696	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
697	        db.walletTransaction.create({
698	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
699	        }),
700	      ]);
701	    } else if (p.direction === "down") {
702	      // Downgrade credit was given but hardware unchanged → claw the credit back.
703	      // Guarded so it can never drive the balance negative; if the customer already
704	      // spent it, we log and leave it (best-effort — they keep a small windfall).
705	      await db.$transaction(async (tx) => {
706	        await debitWallet(tx, server.userId, cents);
707	        await tx.walletTransaction.create({
708	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
709	        });
710	      });
711	    }
712	    await db.auditLog.create({
713	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
714	    });
715	  } catch (e: any) {
716	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
717	    await db.auditLog.create({
718	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
719	    }).catch(() => {});
720	  }
721	}
