723	async function runJob(job: Job) {
724	  // The job is already atomically claimed (status RUNNING, attempts incremented)
725	  // by the loop's compare-and-swap before we get here — see the CAS in main().
726	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
727	  try {
728	    await handlers[job.type](job);
729	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
730	    console.log(`[worker] job ${job.id} DONE`);
731	  } catch (e: any) {
732	    const error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`.slice(0, 2000);
733	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
734	    const current = await db.job.findUnique({ where: { id: job.id } });
735	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
736	    await db.job.update({
737	      where: { id: job.id },
738	      data: { status: retriable ? "QUEUED" : "FAILED", error },
739	    });
740	    if (!retriable) {
741	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
742	      if (job.serverId) {
743	        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
744	        if (stillExists) {
745	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
746	        }
747	      }
748	    }
749	  }
750	}
