752	/**
753	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
754	 * killed worker leaves a job RUNNING forever, which permanently blocks the
755	 * server's "one in-flight job" guard and strands it in a transitional state.
756	 */
757	async function reapStuckJobs() {
758	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
759	  for (const job of stuck) {
760	    const retriable = job.attempts < MAX_ATTEMPTS;
761	    await db.job.update({
762	      where: { id: job.id },
763	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
764	    });
765	    if (!retriable) {
766	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
767	      if (job.serverId) {
768	        const s = await db.server.findUnique({ where: { id: job.serverId } });
769	        if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
770	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
771	        }
772	      }
773	    }
