10	/**
11	 * Game-server auto-update handlers.
12	 *
13	 * `gameUpdate` runs a best-effort, per-family update command over SSH against
14	 * the server's private IP (the worker can reach vmbr1). `gameUpdateSweep` finds
15	 * RUNNING game servers with `autoUpdate=true` and enqueues GAME_UPDATE jobs for
16	 * them — safe to call periodically (it de-dupes on in-flight jobs).
17	 *
18	 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire these
19	 * in there (`GAME_UPDATE: gameUpdate`) and call `gameUpdateSweep()` on a timer.
20	 */
21	
22	/** Steam dedicated-server app IDs for steamcmd-based families. */
23	const STEAM_APPID: Partial<Record<GameFamily, string>> = {
24	  valheim: "896660",
25	  rust: "258550",
26	  palworld: "2394010",
27	  cs2: "730",
28	};
29	
30	/** systemd service name candidates per family (first that exists wins). */
31	const SERVICE_HINT: Record<GameFamily, string> = {
32	  minecraft: "minecraft",
33	  valheim: "valheim",
34	  rust: "rust",
35	  palworld: "palworld",
36	  cs2: "cs2",
37	  terraria: "terraria",
38	};
39	
40	/**
41	 * Build a best-effort remote update command. For steamcmd-based games we run an
42	 * anonymous `app_update ... validate` if steamcmd is present, then (always)
43	 * restart the matching systemd service. Everything is tolerant (`|| true`) so a
44	 * missing tool/service never fails the whole job for an otherwise-healthy VM.
45	 */
46	function updateCommand(family: GameFamily): string {
47	  const appId = STEAM_APPID[family];
48	  const svc = SERVICE_HINT[family];
49	  const steam = appId
50	    ? `if command -v steamcmd >/dev/null 2>&1; then steamcmd +login anonymous +app_update ${appId} validate +quit || true; fi; `
51	    : "";
52	  // Restart the named service, then a "<family>-server" variant, then any unit
53	  // whose name contains the family; never hard-fail.
54	  const restart =
55	    `systemctl restart ${svc} 2>/dev/null || ` +
56	    `systemctl restart ${svc}-server 2>/dev/null || ` +
57	    `svc=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${family} | head -1 | awk '{print $1}'); ` +
58	    `if [ -n "$svc" ]; then systemctl restart "$svc" || true; fi`;
59	  return `set -e; ${steam}${restart}; true`;
60	}
61	
62	async function loadGameServer(serverId: string) {
63	  const server = await db.server.findUnique({
64	    where: { id: serverId },
65	    include: { osTemplate: true },
66	  });
67	  if (!server) throw new Error(`Server ${serverId} not found`);
68	  return server;
69	}
