128	/**
129	 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
130	 * auto-update and has no job already in flight. Idempotent / safe to call on a
131	 * timer. Returns nothing; logs a summary.
132	 */
133	export async function gameUpdateSweep(): Promise<void> {
134	  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
135	  const candidates = await db.server.findMany({
136	    where: {
137	      status: "RUNNING",
138	      autoUpdate: true,
139	      osTemplate: { family: { in: [...GAME_FAMILIES] } },
140	    },
141	    select: { id: true, hostname: true },
142	  });
143	  if (candidates.length === 0) return;
144	
145	  let enqueued = 0;
146	  for (const s of candidates) {
147	    const inflight = await db.job.count({
148	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
149	    });
150	    if (inflight > 0) continue;
151	    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
152	    enqueued++;
153	  }
154	  if (enqueued > 0) console.log(`[game-update] sweep enqueued ${enqueued} update job(s)`);
155	}
