207	/** Convert an rwx rights triad ("rwx","r-x","r--") into an octal mode integer. */
208	function rightsToMode(rights: { user: string; group: string; other: string }): number | null {
209	  if (!rights) return null;
210	  const bits = (s: string): number =>
211	    (s.includes("r") ? 4 : 0) + (s.includes("w") ? 2 : 0) + (s.includes("x") ? 1 : 0);
212	  return (bits(rights.user) << 6) | (bits(rights.group) << 3) | bits(rights.other);
213	}
214	
215	function splitPath(p: string): string[] {
216	  return p.split("/").filter((s) => s.length > 0);
217	}
218	
219	function simResolve(serverId: string, p: string): SimNode | null {
220	  let node = simRoot(serverId);
221	  for (const part of splitPath(p)) {
222	    if (node.type !== "dir") return null;
223	    const next = node.children[part];
224	    if (!next) return null;
225	    node = next;
226	  }
227	  return node;
228	}
229	
230	function simParent(serverId: string, p: string): { parent: SimDir; name: string } | null {
231	  const parts = splitPath(p);
232	  if (parts.length === 0) return null;
233	  const name = parts[parts.length - 1];
234	  const parentPath = "/" + parts.slice(0, -1).join("/");
235	  const parent = simResolve(serverId, parentPath);
236	  if (!parent || parent.type !== "dir") return null;
237	  return { parent, name };
238	}
