75	/** Run one command on the server over SSH via sshpass. Never throws. */
76	async function sshExec(
77	  server: { ipAddress: string | null; rootPassword: string | null },
78	  command: string
79	): Promise<{ output: string; failed: boolean }> {
80	  if (!server.ipAddress || !server.rootPassword) {
81	    return { output: "[nxeon] server has no reachable IP or root password", failed: true };
82	  }
83	  // The worker reaches VMs directly on the private bridge (10.20.0.0/24), so we
84	  // connect to the private IP on port 22.
85	  const args = [
86	    "-p",
87	    server.rootPassword,
88	    "ssh",
89	    "-o",
90	    "StrictHostKeyChecking=no",
91	    "-o",
92	    "UserKnownHostsFile=/dev/null",
93	    "-o",
94	    "ConnectTimeout=10",
95	    "-o",
96	    "BatchMode=no",
97	    `root@${server.ipAddress}`,
98	    // Wrap in bash -c with a single-quoted payload so complex commands survive intact.
99	    `bash -c ${shSingleQuote(command)}`,
100	  ];
101	  try {
102	    const { stdout, stderr } = await execFileAsync("sshpass", args, {
103	      timeout: CMD_TIMEOUT_MS,
104	      maxBuffer: 8 * 1024 * 1024,
105	      env: { ...process.env, DEBIAN_FRONTEND: "noninteractive" },
106	    });
107	    const out = `${stdout}${stderr ? `\n${stderr}` : ""}`.trim();
108	    return { output: out || "[no output]", failed: false };
109	  } catch (e: any) {
110	    // execFile rejects on non-zero exit or timeout; capture whatever we got.
111	    const out = `${e?.stdout ?? ""}${e?.stderr ? `\n${e.stderr}` : ""}`.trim();
112	    const reason = e?.killed
113	      ? `[nxeon] command timed out after ${CMD_TIMEOUT_MS / 1000}s`
114	      : `[nxeon] command exited with code ${e?.code ?? "?"}`;
115	    return { output: `${out ? out + "\n" : ""}${reason}`, failed: true };
116	  }
117	}
