123	/** Parse Claude's plan reply into a validated list of steps, or null. */
124	function parsePlan(reply: string): PlanStep[] | null {
125	  const start = reply.indexOf("[");
126	  const end = reply.lastIndexOf("]");
127	  if (start === -1 || end === -1 || end < start) return null;
128	  let raw: unknown;
129	  try {
130	    raw = JSON.parse(reply.slice(start, end + 1));
131	  } catch {
132	    return null;
133	  }
134	  if (!Array.isArray(raw)) return null;
135	  const steps: PlanStep[] = [];
136	  for (const item of raw) {
137	    if (typeof item === "string") {
138	      const cmd = item.trim();
139	      if (cmd) steps.push({ cmd, intent: "" });
140	    } else if (item && typeof item === "object") {
141	      const anyItem = item as Record<string, unknown>;
142	      const cmd = String(anyItem.cmd ?? anyItem.command ?? "").trim();
143	      const intent = String(anyItem.intent ?? anyItem.description ?? "").trim();
144	      if (cmd) steps.push({ cmd, intent });
145	    }
146	  }
147	  return steps.length ? steps : null;
148	}
