async function loadMigration(job: Job) {
  const payload = (job.payload ?? {}) as MigratePayload;
  if (!payload.migrationId) throw new Error("migrate job: missing migrationId");
  const migration = await db.migration.findUnique({ where: { id: payload.migrationId } });
  if (!migration) throw new Error(`Migration ${payload.migrationId} not found`);
  // Migration has no Prisma relation to Server (serverId is a plain FK) — resolve
  // the target server row separately. `dedicatedIp` is needed by the real engine
  // to compute the SSH connection target.
  const server = await db.server.findUnique({
    where: { id: migration.serverId },
    include: { dedicatedIp: true },
  });
  return { ...migration, server };
}

